/* ---------------- 发音 ---------------- */
const POS_ABBR = { n: "名", v: "动", adj: "形", adv: "副", prep: "介", conj: "连", pron: "代",
  num: "数", art: "冠", int: "叹", pl: "复", pref: "前", suf: "后", abbr: "缩" };

// 例句里高亮目标词：兼容 -s/-es/-ed/-ing/-ly/-er/-est/复数变形
function highlightWord(parent, text, w) {
  const esc = String(w).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  let re;
  try {
    re = new RegExp("\\b(" + esc + "(?:s|es|ed|d|ing|ly|er|est|ies|ied)?)\\b", "gi");
  } catch (e) {
    parent.createSpan({ text });
    return;
  }
  let last = 0;
  let m;
  let hit = false;
  while ((m = re.exec(text)) !== null) {
    hit = true;
    if (m.index > last) parent.createSpan({ text: text.slice(last, m.index) });
    parent.createSpan({ cls: "hll-hl", text: m[0] });
    last = m.index + m[0].length;
    if (m.index === re.lastIndex) re.lastIndex += 1;
  }
  if (!hit) {
    parent.createSpan({ text });
    return;
  }
  if (last < text.length) parent.createSpan({ text: text.slice(last) });
}

// 释义按「名 / 动 / 形 …」分段，词性做成小标签，避免看着像错字
function renderSenses(parent, zh) {
  const POS = "名动形副介连代数量叹助拟复前冠缩";
  const parts = String(zh || "").split(/[；;]/).map((x) => x.trim()).filter(Boolean);
  parts.forEach((seg) => {
    const row = parent.createDiv({ cls: "hll-sense" });
    let m = seg.match(new RegExp(`^([${POS}])\\s*([\\s\\S]*)$`));
    if (!m) {
      const ab = seg.match(/^([a-zA-Z]{1,5})\.\s*([\s\S]*)$/);
      if (ab && POS_ABBR[ab[1].toLowerCase()]) m = [seg, POS_ABBR[ab[1].toLowerCase()], ab[2]];
    }
    if (m) {
      row.createSpan({ cls: "hll-pos", text: m[1] });
      row.createSpan({ cls: "hll-sense-text", text: m[2] });
    } else {
      row.createSpan({ cls: "hll-sense-text", text: seg });
    }
  });
}

function speak(word, rate = 0.9) {
  try {
    const synth = window.speechSynthesis;
    if (synth) {
      synth.cancel();
      const u = new window.SpeechSynthesisUtterance(word);
      u.lang = "en-US";
      u.rate = rate;
      u.pitch = 1;
      synth.speak(u);
      return "tts";
    }
  } catch (e) { /* 落到下面的在线音频 */ }
  try {
    const a = new Audio(`https://dict.youdao.com/dictvoice?audio=${encodeURIComponent(word)}&type=2`);
    a.play();
    return "audio";
  } catch (e) {
    new Notice("这台设备没有可用的发音引擎");
    return null;
  }
}

class HaoLanguageLearnView extends ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
    this.tab = "words";        // words | grammar
    this.mode = "cards";       // cards | quiz | done
    this.queue = [];
    this.idx = 0;
    this.revealed = false;
    this.quizList = [];
    this.quizIdx = 0;
    this.quizRight = 0;
    this.grammarCat = "all";
    this.openGrammarId = null;
  }

  getViewType() { return VIEW_TYPE; }
  getDisplayText() { return "语言学习"; }
  getIcon() { return "languages"; }

  async onOpen() { await this.render(); }

  async render() {
    const root = this.containerEl.children[1];
    root.empty();
    root.addClass("hll-root");
    const inner = root.createDiv({ cls: "hll-inner" });

    const trial = this.plugin.trialState();
    if (!this.plugin.canUse() || this.forceLicense) {
      this.drawLicense(inner, trial);
      return;
    }
    this.drawHeader(inner);
    const body = inner.createDiv({ cls: "hll-body" });
    if (this.tab === "words") await this.drawWords(body);
    else if (this.tab === "groups") await this.drawGroups(body);
    else await this.drawGrammar(body);
  }

  drawLicense(parent, trial) {
    const t = trial || this.plugin.trialState();
    const box = parent.createDiv({ cls: "hll-license" });
    box.createDiv({ cls: "hll-license-badge", text: t.expired ? "试用已结束" : "付费插件" });
    box.createEl("h2", { cls: "hll-license-title", text: t.expired ? "试用结束，继续用请激活" : "语言学习 · 需要激活" });
    box.createDiv({ cls: "hll-license-price" }).createSpan({ cls: "hll-price-num", text: PRICE_TEXT });
    box.createDiv({ cls: "hll-license-sub", text: "一次性买断 · 永久更新 · 换设备可重新激活" });

    // 试用状态提示 / 回学习 / 开始试用
    if (t.started && !t.expired) {
      const back = box.createDiv({ cls: "hll-trial-bar" });
      back.createSpan({ cls: "hll-trial-text", text: `试用中，还剩 ${t.daysLeft} 天` });
      const cont = back.createEl("button", { cls: "hll-btn is-primary", text: "继续试用" });
      cont.onclick = () => { this.forceLicense = false; this.render(); };
    } else if (!t.started) {
      const start = box.createDiv({ cls: "hll-trial-start" });
      const b = start.createEl("button", { cls: "hll-btn is-primary", text: `先免费试用 ${t.total} 天` });
      b.onclick = async () => {
        await this.plugin.startTrial();
        this.forceLicense = false;
        new Notice(`已开始 ${t.total} 天试用`);
        this.render();
      };
      start.createSpan({ cls: "hll-trial-hint", text: "不用微信、不用注册，点一下就进；试用期功能全开" });
    } else if (t.expired) {
      box.createDiv({ cls: "hll-trial-expired", text: `你已用完 ${t.total} 天试用。学过的进度都还在，激活后接着学。` });
    }

    const steps = box.createDiv({ cls: "hll-license-steps" });
    const step = (n, text) => {
      const row = steps.createDiv({ cls: "hll-license-step" });
      row.createSpan({ cls: "hll-step-n", text: String(n) });
      row.createSpan({ text });
    };
    step(1, "加作者微信，备注「语言学习插件」");
    step(2, `微信转账 ${PRICE_TEXT}，把转账截图发给作者`);
    step(3, "收到兑换码（较长，整段复制）粘到下面，或导入 .hll 文件");

    const wx = box.createDiv({ cls: "hll-wx" });
    wx.createSpan({ cls: "hll-wx-k", text: "微信" });
    wx.createSpan({ cls: "hll-wx-v", text: WECHAT });
    const copy = wx.createEl("button", { cls: "hll-btn", text: "复制" });
    copy.onclick = async () => {
      try {
        await navigator.clipboard.writeText(WECHAT);
        new Notice("微信号已复制：" + WECHAT);
      } catch (e) {
        new Notice("复制失败，请手动记下：" + WECHAT);
      }
    };

    const form = box.createDiv({ cls: "hll-license-form" });
    const input = form.createEl("textarea", { cls: "hll-license-input" });
    input.rows = 2;
    input.placeholder = "把兑换码整段粘进来（很长是正常的）";
    input.spellcheck = false;
    const btn = form.createEl("button", { cls: "hll-btn is-primary", text: "激活" });
    const err = box.createDiv({ cls: "hll-license-err" });

    const fileRow = box.createDiv({ cls: "hll-license-filerow" });
    const fileBtn = fileRow.createEl("button", { cls: "hll-btn", text: "导入授权文件（.hll）" });
    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.accept = ".hll,.txt,.json";
    fileInput.style.display = "none";
    fileRow.appendChild(fileInput);
    fileBtn.onclick = () => fileInput.click();

    const submit = async () => {
      const val = (input.value || "").trim();
      if (!val) { err.setText("先填兑换码"); return; }
      if (!verifyCode(val)) {
        err.setText("这个码不对。多半是复制时漏了一段——整段重新复制，或直接导入 .hll 授权文件。");
        return;
      }
      await this.plugin.activate(val);
      err.setText("");
      new Notice("激活成功，开始学英语吧");
      this.render();
    };
    fileInput.addEventListener("change", async () => {
      const f = fileInput.files && fileInput.files[0];
      if (!f) return;
      try {
        const text = await f.text();
        let code = text.trim();
        if (code.startsWith("{")) {
          const obj = JSON.parse(code);
          code = obj["兑换码"] || obj.code || obj.license || "";
        }
        input.value = code;
        await submit();
      } catch (e) {
        err.setText("文件读不出来，直接把兑换码粘到上面也一样");
      }
    });
    btn.onclick = submit;
    input.addEventListener("keydown", (ev) => {
      if (ev.key === "Enter") { ev.preventDefault(); submit(); }
    });

    box.createDiv({ cls: "hll-license-foot", text: "兑换码与微信绑定，仅限本人使用；转让或公开分享会被作废。" });
    box.createDiv({ cls: "hll-license-credit", text: "例句语料来自 Tatoeba（CC-BY 2.0 FR）" });
  }

  drawHeader(parent) {
    const head = parent.createDiv({ cls: "hll-head" });
    head.createEl("h2", { cls: "hll-title", text: "语言学习" });
    const ver = (this.plugin.manifest && this.plugin.manifest.version) || "?";
    head.createSpan({ cls: "hll-ver", text: "v" + ver });
    head.createSpan({ cls: "hll-sub", text: "English · 会说 > 会考" });

    // 试用中：右上角挂一个「剩 N 天 · 去购买」的标签
    if (!this.plugin.isLicensed()) {
      const t = this.plugin.trialState();
      if (t.started && !t.expired) {
        const tag = head.createEl("button", { cls: "hll-trial-tag", text: `试用剩 ${t.daysLeft} 天 · 去购买` });
        tag.onclick = () => { this.forceLicense = true; this.render(); };
      }
    }
    const reloadBtn = head.createEl("button", { cls: "hll-ver hll-reload", text: "↻" });
    reloadBtn.title = "重新加载插件（改完代码不用关 Obsidian）";
    reloadBtn.onclick = () => {
      try {
        const pm = this.plugin.app.plugins;
        if (pm && pm.disablePlugin && pm.enablePlugin) {
          pm.disablePlugin(this.plugin.manifest.id);
          pm.enablePlugin(this.plugin.manifest.id);
          new Notice("已重新加载");
          return;
        }
      } catch (e) { /* ignore */ }
      new Notice("请按 Ctrl+R 重新加载应用");
    };

    const tabs = head.createDiv({ cls: "hll-tabs" });
    [["words", "单词学习"], ["groups", "卡组总览"], ["grammar", "语法学习"]].forEach(([k, label]) => {
      const b = tabs.createEl("button", {
        cls: "hll-tab" + (this.tab === k ? " is-active" : ""),
        text: label,
      });
      b.onclick = () => { if (this.tab !== k) { this.tab = k; this.render(); } };
    });
  }

  /* ================= 单词 ================= */
  async drawWords(parent) {
    const db = await this.plugin.loadWords();
    if (!db) {
      parent.createDiv({ cls: "hll-empty", text: "没读到单词库：" + this.plugin.data.settings.wordFile });
      return;
    }
    const groups = db.groups || [];
    const prog = this.plugin.data.progress;
    const gid = Math.min(Math.max(prog.cursor || 1, 1), groups.length);
    const group = groups[gid - 1];
    const mastered = new Set(prog.mastered[gid] || []);
    const doneGroups = Object.keys(prog.done || {}).map(Number).sort((a, b) => a - b);

    if (!this.wordMode) this.wordMode = "study";   // study 学习 | review 复习
    const wrongBook = prog.wrong || {};
    const wrongCount = Object.keys(wrongBook).length;

    // 顶部信息条
    const bar = parent.createDiv({ cls: "hll-bar" });
    const left = bar.createDiv({ cls: "hll-bar-left" });
    const seg = left.createDiv({ cls: "hll-seg" });
    [["study", "学习"], ["review", "复习"]].forEach(([k, label]) => {
      const b = seg.createEl("button", {
        cls: "hll-seg-btn" + (this.wordMode === k ? " is-active" : ""),
        text: label,
      });
      b.onclick = () => {
        if (this.wordMode === k) return;
        this.wordMode = k;
        this.mode = "cards";
        this.queue = [];
        this.idx = 0;
        this.currentGroupId = 0;
        this.render();
      };
    });
    if (this.wordMode === "study") {
      left.createSpan({ cls: "hll-badge", text: `卡组 #${gid}` });
      left.createSpan({ cls: "hll-level", text: group.level });
      left.createSpan({ cls: "hll-muted", text: `${mastered.size}/${group.words.length} 已掌握` });
    } else {
      left.createSpan({ cls: "hll-muted", text: "复习：从学过的词里随机抽，不影响卡组进度" });
    }
    const right = bar.createDiv({ cls: "hll-bar-right" });
    const resetBtn = right.createEl("button", { cls: "hll-icon-btn" });
    setIcon(resetBtn, "rotate-ccw");
    resetBtn.title = `重学卡组 #${gid}（清空这组进度）`;
    resetBtn.onclick = () => this.confirmReset([gid], `卡组 #${gid} ${group.level}`);
    const wrongBtn = right.createEl("button", {
      cls: "hll-btn" + (wrongCount ? "" : ""),
      text: `错题本 ${wrongCount}`,
    });
    wrongBtn.disabled = wrongCount === 0;
    if (!wrongCount) wrongBtn.title = "还没有错题，卡片上点 ☆ 可以加入";
    const quizBtn = right.createEl("button", { cls: "hll-btn", text: "抽查这一组" });
    const nextBtn = right.createEl("button", { cls: "hll-btn is-primary", text: "下一组 →" });
    nextBtn.disabled = mastered.size < group.words.length;
    if (nextBtn.disabled) nextBtn.title = "先把这一组全部标记为「记住了」";

    const bar2 = parent.createDiv({ cls: "hll-progress" });
    const fill = bar2.createDiv({ cls: "hll-progress-fill" });
    fill.style.width = `${Math.round((mastered.size / group.words.length) * 100)}%`;

    const stage = parent.createDiv({ cls: "hll-stage" });

    // 重新构建队列：学习＝本组未掌握；复习＝所有已掌握的词（跨组）
    const poolKey = this.wordMode === "review" ? "review" : gid;
    if (this.mode === "cards") {
      let pool;
      if (this.wordMode === "review") {
        pool = [];
        groups.forEach((g) => {
          const mset = new Set(prog.mastered[g.id] || []);
          g.words.forEach((w) => { if (mset.has(w.w)) pool.push({ ...w, gid: g.id }); });
        });
        pool.sort(() => Math.random() - 0.5);
      } else {
        pool = group.words.filter((w) => !mastered.has(w.w)).map((w) => ({ ...w, gid }));
      }
      if (!this.queue.length || this.currentGroupId !== poolKey) {
        this.queue = pool.slice();
        this.idx = 0;
        this.revealedCard = false;
        this.currentGroupId = poolKey;
      }
      if (this.wordMode === "study") this.queue = this.queue.filter((w) => !mastered.has(w.w));
    }

    if (this.wordMode === "review" && this.mode === "cards" && this.queue.length === 0) {
      const box = stage.createDiv({ cls: "hll-done" });
      box.createDiv({ cls: "hll-done-title", text: "还没有可复习的词" });
      box.createDiv({ cls: "hll-muted", text: "先学一组、标记一些「记住了」，这里就会攒出复习池。" });
      const b = box.createEl("button", { cls: "hll-btn is-primary", text: "回到学习" });
      b.onclick = () => { this.wordMode = "study"; this.queue = []; this.currentGroupId = 0; this.render(); };
    } else if (this.mode === "quiz") { this.drawQuiz(stage, group, gid); }
    else if (this.queue.length === 0 && mastered.size >= group.words.length) {
      const doneBox = stage.createDiv({ cls: "hll-done" });
      doneBox.createDiv({ cls: "hll-done-emoji", text: "✓" });
      doneBox.createDiv({ cls: "hll-done-title", text: `卡组 #${gid} 完成` });
      doneBox.createDiv({ cls: "hll-muted", text: "去抽查一遍，确认不是「眼熟」而是真的记住。" });
      const b = doneBox.createEl("button", { cls: "hll-btn is-primary", text: "抽查这一组" });
      b.onclick = () => { this.startQuiz(group, gid); };
    } else if (this.queue.length === 0) {
      // 剩下的都已掌握但未抽查 —— 直接给下一组
      const box = stage.createDiv({ cls: "hll-done" });
      box.createDiv({ cls: "hll-done-title", text: "这一组已全部标记" });
      box.createDiv({ cls: "hll-muted", text: "可以抽查，或直接进下一组。" });
      const b = box.createEl("button", { cls: "hll-btn is-primary", text: "下一组 →" });
      b.onclick = () => this.goNextGroup();
    } else {
      await this.drawCard(stage, group, gid, mastered);
    }

    // 按钮行为
    wrongBtn.onclick = () => {
      const items = [];
      groups.forEach((g) => g.words.forEach((w) => {
        if (wrongBook[w.w]) items.push({ ...w, gid: g.id, fromWrong: true });
      }));
      if (!items.length) { new Notice("错题本是空的"); return; }
      this.startQuizItems(items, `错题本 · ${items.length} 词`, null);
    };
    quizBtn.onclick = () => this.startQuiz(group, gid);
    nextBtn.onclick = () => this.goNextGroup();

    if (doneGroups.length) {
      const hist = parent.createDiv({ cls: "hll-hist" });
      hist.createDiv({ cls: "hll-hist-title", text: `已练卡组（${doneGroups.length}）` });
      const chips = hist.createDiv({ cls: "hll-chips" });
      doneGroups.slice(-12).forEach((g) => {
        const q = (this.plugin.data.progress.quiz[g] || {});
        const c = chips.createDiv({ cls: "hll-chip" + (g === gid ? " is-now" : "") });
        c.createSpan({ text: `✓ #${g}` });
        if (q.total) c.createSpan({ cls: "hll-chip-q", text: ` ${q.right}/${q.total}` });
        c.title = `完成于 ${this.plugin.data.progress.done[g] || ""}`;
        c.onclick = () => { this.mode = "cards"; this.queue = []; this.currentGroupId = 0; this.plugin.data.progress.cursor = g; this.plugin.saveData(this.plugin.data); this.render(); };
      });
    }
  }

  confirmReset(gids, label) {
    new ConfirmResetModal(this.app, {
      title: `重新学习 ${label}？`,
      desc: "会清空这组的：已掌握的词、过关记录、抽查成绩，以及这组词在错题本里的条目。词库文件不动，清完从第 1 个词重新开始。",
      okText: "清空并重学",
      onOk: async () => {
        const r = await this.plugin.resetGroups(gids);
        if (gids.length === 1) this.plugin.data.progress.cursor = gids[0];
        await this.plugin.saveData(this.plugin.data);
        this.queue = [];
        this.idx = 0;
        this.currentGroupId = 0;
        this.revealedCard = false;
        this.mode = "cards";
        this.multiSel = this.multiSel || new Set();
        this.multiSel.clear();
        new Notice(`已重置 ${r.groups} 组：清掉 ${r.words} 个已掌握词、${r.wrongs} 条错题`);
        this.render();
      },
    }).open();
  }

  async drawCard(stage, group, gid, mastered) {
    const word = this.queue[this.idx];
    if (!word) return;
    const isStudy = this.wordMode !== "review";
    const card = stage.createDiv({ cls: "hll-card" });

    // 顶部：上一个 · 计数 · 下一个 · 错题本 · 发音
    const top = card.createDiv({ cls: "hll-card-top" });
    const prev = top.createEl("button", { cls: "hll-nav", text: "‹" });
    prev.disabled = this.idx <= 0;
    prev.title = "上一个";
    top.createSpan({ cls: "hll-card-idx", text: `${this.idx + 1} / ${this.queue.length}` });
    const next = top.createEl("button", { cls: "hll-nav", text: "›" });
    next.disabled = this.idx >= this.queue.length - 1;
    next.title = "下一个";

    const starred = this.plugin.isWrong(word.w);
    const star = top.createEl("button", { cls: "hll-star" + (starred ? " is-on" : "") });
    setIcon(star, "star");
    star.title = starred ? "移出错题本（已加入）" : "加入错题本";
    const sound = top.createEl("button", { cls: "hll-sound" });
    setIcon(sound, "volume-2");
    sound.title = "发音";

    card.createDiv({ cls: "hll-word", text: word.w });
    if (this.plugin.data.settings.showPhonetic && word.ph) {
      card.createDiv({ cls: "hll-ph", text: word.ph });
    }

    // 释义：常显 or 悬浮显示（不用点）
    const always = this.plugin.data.settings.showMeaning || this.revealedCard;
    const ans = card.createDiv({ cls: "hll-answer" + (always ? "" : " is-ghost") });
    renderSenses(ans, word.zh);
    const hintText = always ? "读一遍，再决定要不要标记" : "鼠标移到卡片上就能看释义（不用点）";
    card.createDiv({ cls: "hll-hint", text: hintText });

    // 例句（英文 + 中文翻译，默认显示 1 句，可展开）
    if (this._exWord !== word.w) { this.showExamples = false; this._exWord = word.w; }
    const exMap = await this.plugin.loadExamples();
    const exs = this.plugin.data.settings.showExample === false ? [] : (Array.isArray(exMap[word.w]) ? exMap[word.w] : []);
    if (exs.length) {
      card.addClass("has-ex");
      const exWrap = card.createDiv({ cls: "hll-examples" + (always ? "" : " is-ghost") });
      const list = this.showExamples ? exs : exs.slice(0, 1);
      list.forEach(([en, zh]) => {
        const row = exWrap.createDiv({ cls: "hll-ex" });
        const line = row.createDiv({ cls: "hll-ex-en" });
        const txt = line.createSpan({ cls: "hll-ex-text" });
        highlightWord(txt, en, word.w);
        const sp = line.createEl("button", { cls: "hll-ex-sound" });
        setIcon(sp, "volume-1");
        sp.title = "读这句";
        sp.onclick = (ev) => { if (ev && ev.stopPropagation) ev.stopPropagation(); speak(en, 0.95); };
        row.createDiv({ cls: "hll-ex-zh", text: zh });
      });
      if (exs.length > 1) {
        const more = card.createEl("button", {
          cls: "hll-mini-link hll-ex-more",
          text: this.showExamples ? "收起例句" : `更多例句 +${exs.length - 1}`,
        });
        more.onclick = (ev) => { if (ev && ev.stopPropagation) ev.stopPropagation(); this.showExamples = !this.showExamples; this.render(); };
      }
    }

    if (!always) {
      card.addEventListener("mouseenter", () => ans.classList.remove("is-ghost"));
      card.addEventListener("mouseleave", () => { if (!this.revealedCard) ans.classList.add("is-ghost"); });
      card.addEventListener("click", (ev) => {
        if (ev.target && ev.target.closest && ev.target.closest("button")) return;
        this.revealedCard = !this.revealedCard;
        this.render();
      });
    }

    const actions = card.createDiv({ cls: "hll-actions" });
    if (isStudy) {
      const again = actions.createEl("button", { cls: "hll-btn", text: "还不熟" });
      const ok = actions.createEl("button", { cls: "hll-btn is-primary", text: "记住了" });
      again.onclick = () => {
        this.revealedCard = false;
        this.queue.push(this.queue.splice(this.idx, 1)[0]);
        if (this.idx >= this.queue.length) this.idx = 0;
        this.render();
      };
      ok.onclick = () => {
        this.revealedCard = false;
        this.plugin.markMastered(word.gid || gid, word.w);
        this.queue.splice(this.idx, 1);
        if (this.idx >= this.queue.length) this.idx = 0;
        this.render();
      };
    } else {
      const skip = actions.createEl("button", { cls: "hll-btn", text: "不再复习这个" });
      const known = actions.createEl("button", { cls: "hll-btn is-primary", text: "下一个 ›" });
      skip.onclick = () => {
        this.plugin.unmarkMastered(word.gid, word.w);
        this.plugin.removeWrong(word.w);
        this.queue.splice(this.idx, 1);
        if (this.idx >= this.queue.length) this.idx = 0;
        this.render();
      };
      known.onclick = () => {
        if (this.idx < this.queue.length - 1) this.idx += 1;
        else this.idx = 0;
        this.revealedCard = false;
        this.render();
      };
    }

    prev.onclick = () => { if (this.idx > 0) { this.idx -= 1; this.revealedCard = false; this.render(); } };
    next.onclick = () => {
      if (this.idx < this.queue.length - 1) { this.idx += 1; this.revealedCard = false; this.render(); }
    };
    star.onclick = () => {
      if (this.plugin.isWrong(word.w)) this.plugin.removeWrong(word.w);
      else this.plugin.addWrong(word.w, word.gid || gid);
      this.render();
    };
    sound.onclick = () => speak(word.w, this.plugin.data.settings.rate);

    if (this.plugin.data.settings.autoSpeak) speak(word.w, this.plugin.data.settings.rate);
  }

  // items: [{w, ph, zh, gid}]；singleGid 非空时全对才把这一组记为过关
  startQuizItems(items, label, singleGid) {
    this.quizList = items.slice().sort(() => Math.random() - 0.5);
    this.quizIdx = 0;
    this.quizRight = 0;
    this.revealed = false;
    this.quizGid = singleGid || null;
    this.quizLabel = label || "";
    this.mode = "quiz";
    this.tab = "words";
    this.render();
  }

  startQuiz(group, gid) {
    this.startQuizItems(group.words.map((w) => ({ ...w, gid })), `卡组 #${gid}`, gid);
  }

  drawQuiz(stage, group, gid) {
    if (this.quizIdx >= this.quizList.length) {
      const total = this.quizList.length;
      const right = this.quizRight;
      if (this.quizGid) this.plugin.saveQuiz(this.quizGid, right, total);
      if (right === total && this.quizGid) this.plugin.markGroupDone(this.quizGid);
      const box = stage.createDiv({ cls: "hll-done" });
      box.createDiv({ cls: "hll-done-emoji", text: right === total ? "✓" : "…" });
      box.createDiv({ cls: "hll-done-title", text: `抽查结束：${right} / ${total}` });
      if (this.quizLabel) box.createDiv({ cls: "hll-muted", text: this.quizLabel });
      box.createDiv({ cls: "hll-muted", text: right === total ? "这一组过关了，可以进下一组。" : "没过的词回到卡片里，再记一遍。" });
      const actions = box.createDiv({ cls: "hll-actions" });
      if (right === total) {
        const b = actions.createEl("button", { cls: "hll-btn is-primary", text: "下一组 →" });
        b.onclick = () => this.goNextGroup();
      }
      const back = actions.createEl("button", { cls: "hll-btn", text: "回到卡片" });
      back.onclick = () => { this.mode = "cards"; this.render(); };
      return;
    }

    const word = this.quizList[this.quizIdx];
    const card = stage.createDiv({ cls: "hll-card hll-card-quiz" });
    const top = card.createDiv({ cls: "hll-card-top" });
    top.createSpan({ cls: "hll-card-idx", text: `抽查 ${this.quizIdx + 1} / ${this.quizList.length}` });
    if (this.quizLabel) top.createSpan({ cls: "hll-quiz-tag", text: this.quizLabel });
    const sound = top.createEl("button", { cls: "hll-sound", text: "🔊" });
    sound.onclick = () => speak(word.w, this.plugin.data.settings.rate);

    card.createDiv({ cls: "hll-word", text: word.w });
    if (this.plugin.data.settings.showPhonetic && word.ph) card.createDiv({ cls: "hll-ph", text: word.ph });

    const answer = card.createDiv({ cls: "hll-answer" + (this.revealed ? "" : " is-hidden") });
    answer.setText(this.revealed ? word.zh : "点下面「看释义」再对照");

    const actions = card.createDiv({ cls: "hll-actions" });
    if (!this.revealed) {
      const show = actions.createEl("button", { cls: "hll-btn is-primary", text: "看释义" });
      show.onclick = () => { this.revealed = true; this.render(); };
    } else {
      const no = actions.createEl("button", { cls: "hll-btn", text: "没记住" });
      const yes = actions.createEl("button", { cls: "hll-btn is-primary", text: "答对了" });
      const next = (right) => {
        if (right) {
          this.quizRight += 1;
          if (word.fromWrong) this.plugin.removeWrong(word.w);       // 错题答对 → 出书
        } else {
          this.plugin.unmarkMastered(word.gid, word.w);
          if (word.gid) this.plugin.addWrong(word.w, word.gid);      // 答错 → 进书
        }
        this.quizIdx += 1;
        this.revealed = false;
        this.render();
      };
      no.onclick = () => next(false);
      yes.onclick = () => next(true);
    }
  }

  goNextGroup() {
    const prog = this.plugin.data.progress;
    prog.cursor = Math.min((prog.cursor || 1) + 1, 999);
    this.plugin.saveData(this.plugin.data);
    this.mode = "cards";
    this.queue = [];
    this.currentGroupId = 0;
    this.render();
  }

  /* ================= 卡组总览 ================= */
  async drawGroups(parent) {
    const db = await this.plugin.loadWords();
    if (!db) {
      parent.createDiv({ cls: "hll-empty", text: "没读到单词库：" + this.plugin.data.settings.wordFile });
      return;
    }
    const groups = db.groups || [];
    const prog = this.plugin.data.progress;
    const done = prog.done || {};
    const mastered = prog.mastered || {};
    if (!this.levelFilter) this.levelFilter = "all";
    if (!this.statusFilter) this.statusFilter = "all";
    if (!this.multiSel) this.multiSel = new Set();
    if (!this.multiMode) this.multiMode = false;

    const wordTotal = db.meta && db.meta.total ? db.meta.total : groups.reduce((n, g) => n + g.words.length, 0);
    const doneCount = Object.keys(done).length;
    const masteredCount = Object.values(mastered).reduce((n, arr) => n + (arr ? arr.length : 0), 0);

    // 统计
    const stats = parent.createDiv({ cls: "hll-stats" });
    [["总卡组", groups.length + " 组"], ["总词量", wordTotal + " 词"],
     ["已练卡组", doneCount + " 组"], ["已掌握", masteredCount + " 词"]].forEach(([k, v]) => {
      const box = stats.createDiv({ cls: "hll-stat" });
      box.createSpan({ cls: "hll-stat-k", text: k });
      box.createSpan({ cls: "hll-stat-v", text: v });
    });

    // 难度筛选
    const levelDefs = [
      ["all", "全部", groups.length],
      ["初级", "初级", groups.filter((g) => g.level === "初级").length],
      ["中级", "中级", groups.filter((g) => g.level === "中级").length],
      ["高级", "高级", groups.filter((g) => g.level === "高级").length],
    ];
    const chips = parent.createDiv({ cls: "hll-chips hll-cats" });
    levelDefs.forEach(([id, name, n]) => {
      const b = chips.createEl("button", {
        cls: "hll-cat" + (this.levelFilter === id ? " is-active" : ""),
        text: `${name} ${n}`,
      });
      b.onclick = () => { this.levelFilter = id; this.render(); };
    });

    // 完成状态筛选（与难度叠加）
    const levelGroups = groups.filter((g) => this.levelFilter === "all" || g.level === this.levelFilter);
    const cnt = {
      all: levelGroups.length,
      done: levelGroups.filter((g) => !!done[g.id]).length,
      doing: levelGroups.filter((g) => !done[g.id] && (mastered[g.id] || []).length > 0).length,
      none: levelGroups.filter((g) => !done[g.id] && (mastered[g.id] || []).length === 0).length,
    };
    const sChips = parent.createDiv({ cls: "hll-chips hll-cats hll-status-chips" });
    [["all", "全部状态", cnt.all], ["done", "✓ 已过关", cnt.done],
     ["doing", "练过一部分", cnt.doing], ["none", "未开始", cnt.none]].forEach(([id, name, n]) => {
      const b = sChips.createEl("button", {
        cls: "hll-cat" + (this.statusFilter === id ? " is-active" : ""),
        text: `${name} ${n}`,
      });
      b.onclick = () => { this.statusFilter = id; this.render(); };
    });

    // 多选开关 + 操作条
    const bar = parent.createDiv({ cls: "hll-bar hll-gbar" });
    const left = bar.createDiv({ cls: "hll-bar-left" });
    const multiBtn = left.createEl("button", {
      cls: "hll-btn" + (this.multiMode ? " is-primary" : ""),
      text: this.multiMode ? "多选中…（点卡片选择）" : "多选抽查",
    });
    multiBtn.onclick = () => {
      this.multiMode = !this.multiMode;
      if (!this.multiMode) this.multiSel.clear();
      this.render();
    };
    if (this.multiMode) {
      left.createSpan({ cls: "hll-muted", text: `已选 ${this.multiSel.size} 组` });
      const clear = left.createEl("button", { cls: "hll-mini-link", text: "清空" });
      clear.onclick = () => { this.multiSel.clear(); this.render(); };
    }
    const right = bar.createDiv({ cls: "hll-bar-right" });
    const resetSel = right.createEl("button", { cls: "hll-btn is-danger", text: "重置所选" });
    resetSel.disabled = this.multiSel.size === 0;
    resetSel.onclick = () => {
      const ids = [...this.multiSel];
      const names = ids.slice(0, 4).map((id) => `#${id}`).join("、") + (ids.length > 4 ? ` 等 ${ids.length} 组` : "");
      this.confirmReset(ids, names);
    };
    const quizSel = right.createEl("button", { cls: "hll-btn is-primary", text: "抽查所选" });
    quizSel.disabled = this.multiSel.size === 0;
    quizSel.onclick = () => {
      const picked = groups.filter((g) => this.multiSel.has(g.id));
      const items = [];
      picked.forEach((g) => g.words.forEach((w) => items.push({ ...w, gid: g.id })));
      const label = `所选 ${picked.length} 组 · ${items.length} 词`;
      this.startQuizItems(items, label, null);
    };

    // 卡组网格
    const list = levelGroups.filter((g) => {
      const m = (mastered[g.id] || []).length;
      const isDone = !!done[g.id];
      if (this.statusFilter === "done") return isDone;
      if (this.statusFilter === "doing") return !isDone && m > 0;
      if (this.statusFilter === "none") return !isDone && m === 0;
      return true;
    });
    if (!list.length) {
      parent.createDiv({ cls: "hll-empty", text: "这组筛选下没有卡组，换个状态看看" });
      return;
    }
    const grid = parent.createDiv({ cls: "hll-grid" });
    list.forEach((g) => {
      const m = (mastered[g.id] || []).length;
      const isDone = !!done[g.id];
      const isCur = (prog.cursor || 1) === g.id;
      const tile = grid.createDiv({
        cls: "hll-tile"
          + (isDone ? " is-done" : m > 0 ? " is-partial" : "")
          + (isCur ? " is-current" : "")
          + (this.multiSel.has(g.id) ? " is-sel" : ""),
      });
      tile.createDiv({ cls: "hll-tile-id", text: "#" + g.id });
      tile.createDiv({ cls: "hll-tile-meta", text: isDone ? `✓ ${m}/20` : `${m}/20` });
      if (isDone) tile.createDiv({ cls: "hll-tile-date", text: (done[g.id] || "").slice(5) });
      tile.onclick = () => {
        if (this.multiMode) {
          if (this.multiSel.has(g.id)) this.multiSel.delete(g.id); else this.multiSel.add(g.id);
          this.render();
        } else {
          prog.cursor = g.id;
          this.plugin.saveData(this.plugin.data);
          this.mode = "cards";
          this.queue = [];
          this.currentGroupId = 0;
          this.revealedCard = false;
          this.tab = "words";
          this.render();
        }
      };
    });

    // 图例
    const legend = parent.createDiv({ cls: "hll-legend" });
    [["is-done", "已过关"], ["is-partial", "练过一部分"], ["is-current", "当前卡组"], ["", "未开始"]].forEach(([cls, label]) => {
      const item = legend.createDiv({ cls: "hll-legend-item" });
      item.createSpan({ cls: "hll-dot " + cls });
      item.createSpan({ text: label });
    });
  }

  /* ================= 语法 ================= */
  async drawGrammar(parent) {
    const db = await this.plugin.loadGrammar();
    if (!db) {
      parent.createDiv({ cls: "hll-empty", text: "没读到语法库：" + this.plugin.data.settings.grammarFile });
      return;
    }
    const cats = [{ id: "all", name: "全部" }].concat(db.categories || []);
    const chips = parent.createDiv({ cls: "hll-chips hll-cats" });
    cats.forEach((c) => {
      const b = chips.createEl("button", {
        cls: "hll-cat" + (this.grammarCat === c.id ? " is-active" : ""),
        text: c.name,
      });
      b.onclick = () => { this.grammarCat = c.id; this.render(); };
    });

    const list = (db.items || []).filter((x) => this.grammarCat === "all" || x.cat === this.grammarCat);
    const wrap = parent.createDiv({ cls: "hll-gram" });
    list.forEach((g) => {
      const row = wrap.createDiv({ cls: "hll-gram-row" });
      const head = row.createDiv({ cls: "hll-gram-head" });
      head.createSpan({ cls: "hll-gram-title", text: g.title });
      head.createSpan({ cls: "hll-gram-pat", text: g.pattern });
      const open = this.openGrammarId === g.id;
      if (open) {
        const body = row.createDiv({ cls: "hll-gram-body" });
        body.createDiv({ cls: "hll-gram-explain", text: g.explain });
        (g.examples || []).forEach((ex) => {
          const line = body.createDiv({ cls: "hll-gram-ex" });
          line.createDiv({ cls: "hll-ex-en", text: ex.en });
          line.createDiv({ cls: "hll-ex-zh", text: ex.zh });
          const s = line.createEl("button", { cls: "hll-sound is-small", text: "🔊" });
          s.onclick = (ev) => { ev.stopPropagation(); speak(ex.en, 0.95); };
        });
        if (g.tip) body.createDiv({ cls: "hll-gram-tip", text: "口语提示：" + g.tip });
      }
      head.onclick = () => { this.openGrammarId = open ? null : g.id; this.render(); };
    });
  }
}

/* ---------------- 主插件 ---------------- */
module.exports = class HaoLanguageLearn extends Plugin {
  async onload() {
    const raw = await this.loadData();
    this.data = Object.assign({}, DEFAULT_DATA, raw || {});
    this.data.settings = Object.assign({}, DEFAULT_SETTINGS, (raw && raw.settings) || {});
    // 进度优先读独立文件（随 vault 同步）；老版本读 data.json 里的 progress 并迁移过来
    const fromFile = await this._readProgress();
    const legacy = (raw && raw.progress) || null;
    this.data.progress = Object.assign({}, DEFAULT_DATA.progress, fromFile || legacy || {});
    if (!fromFile && legacy) this._writeProgress(this.data.progress);

    this._wordCache = null;
    this._gramCache = null;
    this._exCache = null;

    this.registerView(VIEW_TYPE, (leaf) => new HaoLanguageLearnView(leaf, this));

    // 词库/语法库被改动时，清缓存并刷新已打开的视图（不依赖插件重载）
    this.registerEvent(this.app.vault.on("modify", (f) => {
      const wp = this.data.settings.wordFile;
      const gp = this.data.settings.grammarFile;
      if (!f || !f.path) return;
      const ep = this.data.settings.exampleFile;
      if (f.path === wp) this._wordCache = null;
      else if (f.path === gp) this._gramCache = null;
      else if (ep && f.path === ep) this._exCache = null;
      else return;
      this.app.workspace.getLeavesOfType(VIEW_TYPE).forEach((leaf) => {
        if (leaf.view && typeof leaf.view.render === "function") leaf.view.render();
      });
    }));
    this.addRibbonIcon("languages", "语言学习", () => this.activateView());
    this.addCommand({ id: "open-language-learn", name: "打开语言学习", callback: () => this.activateView() });
    // 不关 Obsidian 也能换上新代码：热重载不可用时用这条兜底
    this.addCommand({
      id: "reload-language-learn",
      name: "重新加载语言学习插件（无需重启）",
      callback: () => {
        try {
          const pm = this.app.plugins;
          if (pm && typeof pm.disablePlugin === "function" && typeof pm.enablePlugin === "function") {
            pm.disablePlugin(this.manifest.id);
            pm.enablePlugin(this.manifest.id);
            new Notice("HaoLanguageLearn 已重新加载");
            return;
          }
        } catch (e) { /* 落到下面的提示 */ }
        new Notice("没法自动重载：命令面板执行「Reload app without saving」（Ctrl+R）即可");
      },
    });
    this.addCommand({
      id: "export-language-progress",
      name: "导出学习进度（.hllp）",
      callback: () => {
        const r = this.exportProgress();
        new Notice(r.ok ? `已导出 ${r.words} 个词 → ${r.name}` : `导出失败：${r.error}`);
      },
    });
    this.addCommand({
      id: "import-language-progress",
      name: "导入学习进度（.hllp）",
      callback: () => this.pickProgressFile(),
    });
    this.addSettingTab(new HaoLangSettingTab(this.app, this));
  }

  onunload() { /* 视图由 Obsidian 回收 */ }

  async activateView() {
    const { workspace } = this.app;
    let leaf = workspace.getLeavesOfType(VIEW_TYPE)[0];
    if (!leaf) {
      leaf = workspace.getLeaf(true);
      await leaf.setViewState({ type: VIEW_TYPE, active: true });
    }
    workspace.revealLeaf(leaf);
  }

  // ---- 学习进度导出 / 导入（离线搬进度：换电脑、备份）----
  _countMastered(prog) {
    const m = (prog && prog.mastered) || {};
    return Object.keys(m).reduce((n, g) => n + (Array.isArray(m[g]) ? m[g].length : 0), 0);
  }

  exportProgress() {
    const prog = this.data.progress || EMPTY_PROGRESS;
    const d = new Date();
    const pad = (n) => String(n).padStart(2, "0");
    const stamp = `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}`;
    const payload = {
      "产品": "HaoLanguageLearn",
      "格式": "hllp/1",
      "导出时间": `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`,
      "摘要": { "已掌握词": this._countMastered(prog), "过关组": Object.keys(prog.done || {}).length },
      "进度": prog,
    };
    const name = `HaoLanguageLearn-学习进度-${stamp}.hllp`;
    const text = JSON.stringify(payload, null, 2);
    try {
      const blob = new Blob([text], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = name;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 4000);
      return { ok: true, name, words: this._countMastered(prog) };
    } catch (e) {
      return { ok: false, error: String(e && e.message || e) };
    }
  }

  // 只增不减：按组合并已掌握词、按词合并错题本，过关记录取缺失的
  mergeProgress(src) {
    const p = this.data.progress || (this.data.progress = Object.assign({}, EMPTY_PROGRESS));
    ["mastered", "done", "quiz", "wrong"].forEach((k) => { if (!p[k] || typeof p[k] !== "object") p[k] = {}; });
    const stat = { words: 0, groups: 0, wrongs: 0, done: 0 };
    const sm = (src && src.mastered) || {};
    Object.keys(sm).forEach((gid) => {
      const arr = Array.isArray(sm[gid]) ? sm[gid] : [];
      if (!arr.length) return;
      const cur = Array.isArray(p.mastered[gid]) ? p.mastered[gid] : (p.mastered[gid] = []);
      const set = new Set(cur);
      let added = 0;
      arr.forEach((w) => { if (w && !set.has(w)) { cur.push(w); set.add(w); added++; } });
      if (added) { stat.words += added; stat.groups += 1; }
    });
    const sd = (src && src.done) || {};
    Object.keys(sd).forEach((gid) => { if (!p.done[gid]) { p.done[gid] = sd[gid]; stat.done += 1; } });
    const sq = (src && src.quiz) || {};
    Object.keys(sq).forEach((gid) => {
      const a = p.quiz[gid], b = sq[gid];
      if (!b) return;
      if (!a) { p.quiz[gid] = b; return; }
      const ra = a.total ? a.right / a.total : 0;
      const rb = b.total ? b.right / b.total : 0;
      if (rb > ra) p.quiz[gid] = b;
    });
    const sw = (src && src.wrong) || {};
    Object.keys(sw).forEach((w) => { if (!p.wrong[w]) { p.wrong[w] = sw[w]; stat.wrongs += 1; } });
    return stat;
  }

  parseProgressFile(text) {
    const obj = JSON.parse(text);
    if (!obj || typeof obj !== "object") throw new Error("空文件");
    const prog = obj["进度"] || obj.progress || obj;
    if (!prog || typeof prog !== "object") throw new Error("没有进度字段");
    if (!prog.mastered && !prog.done && !prog.wrong && !prog.quiz) throw new Error("不是本插件的进度文件");
    return prog;
  }

  pickProgressFile() {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = ".hllp,.json,application/json";
    input.style.display = "none";
    document.body.appendChild(input);
    input.onchange = async () => {
      const f = input.files && input.files[0];
      input.remove();
      if (!f) return;
      try {
        const prog = this.parseProgressFile(await f.text());
        const stat = this.mergeProgress(prog);
        await this.saveData(this.data);
        this._refreshViews();
        const bits = [];
        if (stat.words) bits.push(`新增 ${stat.words} 个已掌握词（${stat.groups} 组）`);
        if (stat.done) bits.push(`补 ${stat.done} 组过关`);
        if (stat.wrongs) bits.push(`错题 +${stat.wrongs}`);
        new Notice(bits.length ? `导入完成：${bits.join("，")}` : "导入完成：没有比本机更新的进度");
      } catch (e) {
        new Notice("导入失败：这不是本插件导出的进度文件");
      }
    };
    input.click();
  }

  _refreshViews() {
    this.app.workspace.getLeavesOfType(VIEW_TYPE).forEach((leaf) => {
      if (leaf.view && typeof leaf.view.render === "function") leaf.view.render();
    });
  }

  // 内嵌词库（社区目录安装只拿得到 manifest/main/styles 三个文件，没有 data/ 目录）
  async _embedded(name) {
    const all = EMBEDDED_DATA;
    if (!all || !all[name]) return null;
    try {
      const bin = atob(all[name]);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      if (typeof DecompressionStream === "undefined") return null;
      const ds = new DecompressionStream("gzip");
      const stream = new Blob([bytes]).stream().pipeThrough(ds);
      const text = await new Response(stream).text();
      return JSON.parse(text);
    } catch (e) {
      return null;
    }
  }

  // 依次尝试：用户配置的路径 → 插件自带 data/ 目录 → 内嵌数据
  async _readJson(candidates, label) {
    for (const raw of candidates) {
      const path = String(raw || "").trim();
      if (!path) continue;
      try {
        const f = this.app.vault.getAbstractFileByPath(path);
        if (f) return JSON.parse(await this.app.vault.read(f));
        const ad = this.app.vault.adapter;
        if (ad && (await ad.exists(path))) return JSON.parse(await ad.read(path));
      } catch (e) {
        new Notice(`${label}读取失败：${path} — ${e.message}`);
      }
    }
    const emb = await this._embedded(label === "单词库" ? "单词库" : label === "语法库" ? "语法库" : "例句库");
    return emb || null;
  }

  _bundled(name) {
    const dir = (this.manifest && this.manifest.dir) || (this.app.vault.configDir + "/plugins/" + (this.manifest && this.manifest.id));
    return dir + "/data/" + name;
  }

  async loadWords() {
    if (this._wordCache) return this._wordCache;
    const data = await this._readJson([this.data.settings.wordFile, this._bundled("单词库.json")], "单词库");
    if (!data) {
      new Notice("找不到单词库：设置里填路径，或把 单词库.json 放到插件 data/ 目录");
      return null;
    }
    this._wordCache = data;
    return data;
  }

  async loadGrammar() {
    if (this._gramCache) return this._gramCache;
    const data = await this._readJson([this.data.settings.grammarFile, this._bundled("语法库.json")], "语法库");
    if (!data) return null;
    this._gramCache = data;
    return data;
  }

  markMastered(gid, word) {
    const p = this.data.progress;
    p.mastered[gid] = p.mastered[gid] || [];
    if (!p.mastered[gid].includes(word)) p.mastered[gid].push(word);
    this.saveData(this.data);
  }

  unmarkMastered(gid, word) {
    const p = this.data.progress;
    p.mastered[gid] = (p.mastered[gid] || []).filter((w) => w !== word);
    this.saveData(this.data);
  }

  markGroupDone(gid) {
    const p = this.data.progress;
    const d = new Date();
    const iso = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
    p.done[gid] = iso;
    p.lastGroup = gid;
    this.saveData(this.data);
  }

  async _readProgress() {
    const path = this.data.settings.progressFile;
    if (!path) return null;
    const ad = this.app.vault.adapter;
    try {
      if (!(await ad.exists(path))) return null;
      return JSON.parse(await ad.read(path));
    } catch (e) {
      return null;
    }
  }

  async _writeProgress(prog) {
    const path = this.data.settings.progressFile;
    if (!path) return;
    const ad = this.app.vault.adapter;
    try {
      const dir = path.split("/").slice(0, -1).join("/");
      if (dir && !(await ad.exists(dir))) await ad.mkdir(dir);
      await ad.write(path, JSON.stringify(prog || {}, null, 2) + "\n");
    } catch (e) {
      console.warn("[HaoLanguageLearn] 进度写入失败", e);
    }
  }

  // 覆盖：data.json 只留本机属性（授权/试用/设置），学习进度写进 vault 里的独立文件
  async saveData(data) {
    const d = data || this.data;
    const local = { license: d.license || null, trial: d.trial || null, settings: d.settings || {} };
    await super.saveData(local);
    await this._writeProgress(d.progress);
  }

  _trialKey() {
    let name = "vault";
    try { name = this.app.vault.getName ? this.app.vault.getName() : "vault"; } catch (e) { /* ignore */ }
    return "haolanguagelearn.trial." + name;
  }

  // 取 data.json 与 localStorage 里更早的时间，删一个也归不了零
  trialStart() {
    const a = (this.data.trial && this.data.trial.start) || 0;
    let b = 0;
    try { b = Number(localStorage.getItem(this._trialKey())) || 0; } catch (e) { /* ignore */ }
    const vals = [a, b].filter((x) => x > 0);
    return vals.length ? Math.min(...vals) : 0;
  }

  trialState() {
    const total = Math.max(1, Number(this.data.settings.trialDays) || 7);
    const start = this.trialStart();
    if (!start) return { started: false, total, daysLeft: total, expired: false };
    const used = Math.floor((Date.now() - start) / 86400000);
    const daysLeft = Math.max(0, total - used);
    return { started: true, start, total, used, daysLeft, expired: daysLeft <= 0 };
  }

  async startTrial() {
    const now = Date.now();
    this.data.trial = { start: now };
    try { localStorage.setItem(this._trialKey(), String(now)); } catch (e) { /* ignore */ }
    await this.saveData(this.data);
  }

  canUse() {
    if (this.isLicensed()) return true;
    const t = this.trialState();
    return t.started && !t.expired;
  }

  isLicensed() {
    const l = this.data && this.data.license;
    if (!l || !l.code) return false;
    // ECDSA 单次约 50ms，渲染路径不能每次都算
    if (!this._licCache) this._licCache = new Map();
    const hit = this._licCache.get(l.code);
    if (hit !== undefined) return hit;
    const ok = verifyCode(l.code);
    this._licCache.set(l.code, ok);
    return ok;
  }

  async activate(code) {
    const norm = formatCode(code);
    if (!verifyCode(norm)) return false;
    this.data.license = { code: norm, at: Date.now() };
    await this.saveData(this.data);
    return true;
  }

  async deactivate() {
    this.data.license = null;
    await this.saveData(this.data);
  }

  async loadExamples() {
    if (this._exCache) return this._exCache;
    const data = await this._readJson([this.data.settings.exampleFile, this._bundled("例句库.json")], "例句库");
    this._exCache = data && typeof data === "object" ? data : {};
    return this._exCache;
  }

  // 重置一组的全部进度：掌握词、过关记录、抽查成绩、以及这组词在错题本里的条目
  async resetGroups(gids) {
    const p = this.data.progress;
    const ids = new Set(gids.map(String));
    let words = 0, wrongs = 0;
    ids.forEach((gid) => {
      words += ((p.mastered || {})[gid] || []).length;
      delete (p.mastered || {})[gid];
      delete (p.done || {})[gid];
      delete (p.quiz || {})[gid];
    });
    const wb = p.wrong || {};
    Object.keys(wb).forEach((k) => {
      if (ids.has(String(wb[k].gid))) { delete wb[k]; wrongs += 1; }
    });
    await this.saveData(this.data);
    return { groups: ids.size, words, wrongs };
  }

  addWrong(word, gid) {
    const wb = (this.data.progress.wrong = this.data.progress.wrong || {});
    const cur = wb[word] || { gid, n: 0 };
    wb[word] = { gid: cur.gid || gid, n: (cur.n || 0) + 1, at: Date.now() };
    this.saveData(this.data);
  }

  removeWrong(word) {
    const wb = this.data.progress.wrong || {};
    if (wb[word]) { delete wb[word]; this.saveData(this.data); }
  }

  isWrong(word) {
    return !!(this.data.progress.wrong || {})[word];
  }

  saveQuiz(gid, right, total) {
    this.data.progress.quiz[gid] = { right, total, at: Date.now() };
    this.saveData(this.data);
  }
};

class ConfirmResetModal extends Modal {
  constructor(app, opts) {
    super(app);
    this.opts = opts;
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.addClass("hll-confirm");
    contentEl.createEl("h3", { text: this.opts.title });
    contentEl.createEl("p", { cls: "hll-confirm-desc", text: this.opts.desc });
    const bar = contentEl.createDiv({ cls: "hll-modal-bar" });
    const cancel = bar.createEl("button", { cls: "hll-btn", text: "取消" });
    const ok = bar.createEl("button", { cls: "hll-btn is-danger", text: this.opts.okText || "确认重置" });
    cancel.onclick = () => this.close();
    ok.onclick = async () => {
      this.close();
      await this.opts.onOk();
    };
  }
  onClose() {
    this.contentEl.empty();
  }
}

class HaoLangSettingTab extends PluginSettingTab {
  constructor(app, plugin) { super(app, plugin); this.plugin = plugin; }
  display() {
    const { containerEl } = this;
    containerEl.empty();
    containerEl.createEl("h2", { text: "语言学习设置" });

    const lic = this.plugin.data.license;
    const okLic = this.plugin.isLicensed();
    containerEl.createEl("h3", { text: "授权" });
    containerEl.createEl("p", {
      cls: "hll-set-desc",
      text: okLic
        ? `已激活：${lic.code}（${new Date(lic.at || Date.now()).toLocaleDateString("zh-CN")}）· 永久更新`
        : `未激活。本插件 ${PRICE_TEXT} 买断、永久更新；加微信 ${WECHAT} 购买后填入兑换码。`,
    });
    const tr = this.plugin.trialState();
    if (!okLic) {
      containerEl.createEl("p", { cls: "hll-set-desc",
        text: tr.started
          ? (tr.expired ? `试用已结束（${tr.total} 天已用完）` : `试用中，还剩 ${tr.daysLeft} 天`)
          : `还没开始试用，首次打开插件会给你 ${tr.total} 天免费试用。` });
    }
    new Setting(containerEl).setName("兑换码").setDesc("粘贴兑换码后点右侧「激活」")
      .addText((t) => { t.setPlaceholder("粘贴兑换码（很长）"); t.inputEl.dataset.lic = "1"; this._licInput = t; })
      .addButton((b) => b.setButtonText("激活").onClick(async () => {
        const val = (this._licInput && this._licInput.getValue()) || "";
        const done = await this.plugin.activate(val);
        new Notice(done ? "激活成功" : "兑换码无效");
        this.display();
      }));
    if (okLic) {
      new Setting(containerEl).setName("解除激活").setDesc("换机器、或要重新输入别的码时用")
        .addButton((b) => b.setButtonText("解除").setWarning().onClick(async () => {
          await this.plugin.deactivate();
          new Notice("已解除激活");
          this.display();
        }));
    }
    containerEl.createEl("h3", { text: "学习内容" });
    new Setting(containerEl).setName("单词库路径")
      .setDesc("JSON：{ meta, groups: [{id, level, words:[{w,ph,zh}]}] }")
      .addText((t) => t.setValue(this.plugin.data.settings.wordFile).onChange(async (v) => {
        this.plugin.data.settings.wordFile = v.trim();
        this.plugin._wordCache = null;
        await this.plugin.saveData(this.plugin.data);
      }));
    new Setting(containerEl).setName("语法库路径")
      .addText((t) => t.setValue(this.plugin.data.settings.grammarFile).onChange(async (v) => {
        this.plugin.data.settings.grammarFile = v.trim();
        this.plugin._gramCache = null;
        await this.plugin.saveData(this.plugin.data);
      }));
    containerEl.createEl("p", { cls: "hll-set-desc",
      text: "例句语料来自 Tatoeba（tatoeba.org，CC-BY 2.0 FR），已统一转简体。" });
    new Setting(containerEl).setName("例句库路径").setDesc("JSON：{ \"word\": [[英文例句, 中文翻译], ...] }；留空则不显示例句")
      .addText((t) => t.setValue(this.plugin.data.settings.exampleFile || "").onChange(async (v) => {
        this.plugin.data.settings.exampleFile = v.trim();
        this.plugin._exCache = null;
        await this.plugin.saveData(this.plugin.data);
      }));
    new Setting(containerEl).setName("卡片上显示例句").setDesc("每张卡默认显示 1 句，可点「更多例句」展开")
      .addToggle((t) => t.setValue(this.plugin.data.settings.showExample !== false)
        .onChange(async (v) => { this.plugin.data.settings.showExample = v; await this.plugin.saveData(this.plugin.data); }));
    new Setting(containerEl).setName("显示音标").addToggle((t) => t.setValue(!!this.plugin.data.settings.showPhonetic)
      .onChange(async (v) => { this.plugin.data.settings.showPhonetic = v; await this.plugin.saveData(this.plugin.data); }));
    new Setting(containerEl).setName("卡片上显示中文释义").setDesc("关掉后卡片只显示英文，点「看释义」才出现")
      .addToggle((t) => t.setValue(!!this.plugin.data.settings.showMeaning)
        .onChange(async (v) => { this.plugin.data.settings.showMeaning = v; await this.plugin.saveData(this.plugin.data); }));
    new Setting(containerEl).setName("卡片出现时自动发音").addToggle((t) => t.setValue(!!this.plugin.data.settings.autoSpeak)
      .onChange(async (v) => { this.plugin.data.settings.autoSpeak = v; await this.plugin.saveData(this.plugin.data); }));
    new Setting(containerEl).setName("语速").setDesc("0.5 慢 — 1.0 正常")
      .addSlider((s) => s.setLimits(0.5, 1.4, 0.1).setValue(this.plugin.data.settings.rate)
        .setDynamicTooltip()
        .onChange(async (v) => { this.plugin.data.settings.rate = v; await this.plugin.saveData(this.plugin.data); }));

    containerEl.createEl("h3", { text: "学习进度" });
    const prog = this.plugin.data.progress || {};
    const nWords = this.plugin._countMastered(prog);
    const nGroups = Object.keys(prog.done || {}).length;
    const nWrong = Object.keys(prog.wrong || {}).length;
    containerEl.createEl("p", { cls: "hll-set-desc",
      text: `当前：已掌握 ${nWords} 词 · 过关 ${nGroups} 组 · 错题 ${nWrong} 个。进度存在库内文件里，库在同步（Obsidian Sync / 网盘 / git）就会跟着走。` });
    new Setting(containerEl).setName("进度文件路径").setDesc("换电脑时两边指向同一路径即可；留空则只用 data.json")
      .addText((t) => t.setValue(this.plugin.data.settings.progressFile || "").onChange(async (v) => {
        this.plugin.data.settings.progressFile = v.trim();
        await this.plugin.saveData(this.plugin.data);
      }));
    new Setting(containerEl).setName("导出学习进度")
      .setDesc("生成一个 .hllp 文件（含已掌握词、过关记录、抽查成绩、错题本），发到另一台电脑后导入")
      .addButton((b) => b.setButtonText("导出").onClick(() => {
        const r = this.plugin.exportProgress();
        new Notice(r.ok ? `已导出 ${r.words} 个词 → ${r.name}` : `导出失败：${r.error}`);
      }));
    new Setting(containerEl).setName("导入学习进度")
      .setDesc("只增不减：合并进现有进度，不会覆盖或清空本机的词与错题")
      .addButton((b) => b.setButtonText("选择文件").setCta().onClick(() => this.plugin.pickProgressFile()));
  }
}

module.exports.HaoLanguageLearnView = HaoLanguageLearnView;
